// Resource requirements for typed build ops (see docs/scope.md §6).
// Invocations are literal argv generated by the catalog, so classification is exact:
// we only reuse resolveBuildResources() for workspace keys, daemon env and heap hints.
import { resolveBuildResources } from "../build.mjs";

const NOT_BUILD = Object.freeze({
  kind: "not_build_tool",
  tool: null,
  targetPlatform: null,
  requiresDevice: false,
  requiresHeavySlot: false,
  requiresWorkspaceLock: false,
  workspaceRoot: null,
  resourceKeys: [],
  requestedHeapMb: 0,
});

// Bazel `clean` and `run` are refused by the legacy argv classifier (it treated them as
// lifecycle/long-running). Typed ops allow both, bounded by workspace serialization and
// timeoutSec, so we classify a neutral `build` invocation for the same workspace instead.
function classifiableArgs(op, inv) {
  if (op.system === "bazel" && (inv.args[0] === "clean" || inv.args[0] === "run")) {
    return ["build"];
  }
  return inv.args;
}

export function resolveOpBuildRequirements(op, params, invocations, { env = process.env, resolve = resolveBuildResources } = {}) {
  if (op.kind !== "build") {
    return {
      ...NOT_BUILD,
      resourceKeys: [],
      kind: op.readOnly ? "read_only" : "not_build_tool",
      requiresDevice: op.kind === "device" || op.kind === "snapshot",
      targetPlatform: op.platform || null,
    };
  }
  const deviceCoupled = Boolean(op.deviceCoupled && op.deviceCoupled(params));
  let merged = null;
  for (const inv of invocations) {
    const r = resolve(inv.cmd, classifiableArgs(op, inv), inv.cwd || process.cwd(), { env, forceBuild: true, workspace: inv.cwd || null });
    if (!r || r.kind === "not_build_tool") continue;
    if (!merged) {
      merged = { ...r, resourceKeys: [...(r.resourceKeys || [])] };
      continue;
    }
    for (const k of r.resourceKeys || []) if (!merged.resourceKeys.includes(k)) merged.resourceKeys.push(k);
    merged.requiresHeavySlot = merged.requiresHeavySlot || r.requiresHeavySlot;
    merged.requiresWorkspaceLock = merged.requiresWorkspaceLock || r.requiresWorkspaceLock;
    merged.requestedHeapMb = Math.max(merged.requestedHeapMb || 0, r.requestedHeapMb || 0);
  }
  if (!merged) {
    merged = { ...NOT_BUILD, resourceKeys: [], tool: op.system === "xcode" ? "xcodebuild" : op.system };
  }
  merged.tool = merged.tool || (op.system === "xcode" ? "xcodebuild" : op.system);
  if (!merged.workspaceRoot) merged.workspaceRoot = invocations[0]?.cwd || process.cwd();
  if (merged.resourceKeys.length === 0) merged.resourceKeys = [`${op.system}:${merged.workspaceRoot}`];
  merged.requiresWorkspaceLock = true;
  merged.requiresHeavySlot = true;
  merged.requiresDevice = deviceCoupled;
  merged.kind = deviceCoupled ? "device_coupled_build" : "pure_build";
  merged.targetPlatform = deviceCoupled ? op.devicePlatform || null : null;
  if (params.ramMb) merged.requestedHeapMb = Math.max(merged.requestedHeapMb || 0, params.ramMb);
  delete merged.reason;
  delete merged.rejectReason;
  return merged;
}
